    Queue queue;
    QInit(&queue);
    int failed = 0;
    while (1) {
        int choice = getchar();
        if (choice == EOF) break;
        if (choice != '\n') {
            int tail;
            while ((tail = getchar()) != '\n' && tail != EOF) {}
        }
        if (choice == 'q') break;
        if (choice == 'a') {
            Item value = 0;
            int status = read_integer(&value);
            if (status == 0) break;
            if (status < 0) {
                if (ferror(stdin)) { failed = 1; break; }
                puts("INVALID INTEGER");
                continue;
            }
            puts(QPush(value, &queue) ? "ADDED" : "ADD FAILED");
        } else if (choice == 'd') {
            Item value = 0;
            if (QPop(&value, &queue)) printf("REMOVED %d\n", value);
            else puts("EMPTY");
        } else { puts("INVALID MENU"); continue; }
        printf("count=%d\n", QCount(&queue));
    }
    if (ferror(stdin)) failed = 1;
    QClear(&queue);
    return failed;
}

