#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <ctype.h>
#include <limits.h>
#include "booth_api.h"

static int read_line(char *text, int capacity) {
    if (capacity < 2) return -1;
    if (fgets(text, capacity, stdin) == NULL) return ferror(stdin) ? -1 : 0;
    char *end = strchr(text, '\n');
    if (end != NULL) { *end = '\0'; return 1; }
    int ch = getchar();
    if (ch == '\n') return 1;
    if (ch == EOF) return ferror(stdin) ? -1 : 1;
    while (ch != '\n' && ch != EOF) ch = getchar();
    return -1;
}

static int read_integer(int *output) {
    char text[64];
    int status = read_line(text, 64);
    if (status != 1) return status;
    char *end;
    errno = 0;
    long value = strtol(text, &end, 10);
    if (end == text || errno == ERANGE) return -1;
    while (isspace((unsigned char)*end)) end++;
    if (*end != '\0' || value < INT_MIN || value > INT_MAX) return -1;
    *output = (int)value;
    return 1;
}

static bool arrives(int rate) {
    return (double)rand() / ((double)RAND_MAX + 1.0) < (double)rate / 60.0;
}
static Item customer(long minute) {
    Item item = {minute, rand() % 3 + 1};
    return item;
}
int main(void) {
    int hours = 0, rate = 0;
    if (read_integer(&hours) != 1 || read_integer(&rate) != 1 ||
        hours < 1 || hours > 24 || rate < 0 || rate > 60) return 1;
    long ticks = 60L * hours;
    long arrived = 0, accepted = 0, rejected = 0, started = 0;
    long queue_sum = 0, wait_sum = 0;
    int busy = 0;
    Queue queue;
    QInit(&queue);
    srand(17u);
    for (long minute = 0; minute < ticks; minute++) {
        if (arrives(rate)) {
            arrived++;
            if (QFull(&queue)) rejected++;
            else {
                Item item = customer(minute);
                if (!QPush(item, &queue)) { QClear(&queue); return 1; }
                accepted++;
            }
        }
        if (busy == 0 && !QEmpty(&queue)) {
            Item item;
            if (!QPop(&item, &queue)) { QClear(&queue); return 1; }
            busy = item.service;
            wait_sum += minute - item.arrival;
            started++;
        }
        if (busy > 0) busy--;
        queue_sum += QCount(&queue);
    }
    printf("arrived=%ld accepted=%ld rejected=%ld\n", arrived, accepted, rejected);
    printf("started=%ld waiting=%d\n", started, QCount(&queue));
    printf("average queue=%.2f\n", (double)queue_sum / (double)ticks);
    if (started > 0) printf("average wait=%.2f\n", (double)wait_sum / (double)started);
